package local.quickpic.tapprobe;
import android.app.*;import android.content.*;import android.os.*;import android.preference.*;import android.view.*;import android.graphics.*;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import org.json.*;
public final class EinkSettingsProbe extends Instrumentation {
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 void click(String text)throws Exception{AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();java.util.List<AccessibilityNodeInfo> a=root.findAccessibilityNodeInfosByText(text);if(a.isEmpty())throw new Exception("Missing "+text);Rect r=new Rect();a.get(0).getBoundsInScreen(r);long t=SystemClock.uptimeMillis();MotionEvent d=MotionEvent.obtain(t,t,0,r.exactCenterX(),r.exactCenterY(),0),u=MotionEvent.obtain(t,t+50,1,r.exactCenterX(),r.exactCenterY(),0);sendPointerSync(d);sendPointerSync(u);d.recycle();u.recycle();waitForIdleSync();SystemClock.sleep(300);}
 @Override public void onStart(){Bundle out=new Bundle();try{Context target=getTargetContext();Intent i=new Intent().setClassName(target,"com.alensw.ui.activity.MainPreference").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);PreferenceActivity a=(PreferenceActivity)startActivitySync(i);waitForIdleSync();SystemClock.sleep(400);click("View");Preference p=a.findPreference("eink_render_mode"),r=a.findPreference("reader_mode");if(p==null||r==null||!p.getClass().getName().equals("com.alensw.jni.EinkPreference"))throw new Exception("Actual image preference missing");if(p.getOrder()!=r.getOrder()+1)throw new Exception("Image setting ordering differs");a.getListView().smoothScrollToPosition(a.getListView().getCount()-1);waitForIdleSync();SystemClock.sleep(400);click("E-ink rendering optimization");if(getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("Lanczos3").isEmpty())throw new Exception("Real setting did not open choices");Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"quickpic24-real-settings.png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();out.putString("stream","{\"status\":\"PASS\",\"actual_settings_entry\":true,\"after_reader_mode\":true,\"dialog_opened_from_settings\":true}\n");finish(0,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream",s.toString());finish(1,out);}}
}
